// src/songs.js
// =====================================================================
//  SONG REGISTRY - add / edit songs here, everything else is automatic.
//  Each song needs: audio file, beatmap JSON, a song-select card image,
//  and a "skin" (what the level looks like).
//
//  >>> ART SWAP GUIDE <<<
//  Every file under assets/mock/ is PLACEHOLDER ART generated by a script.
//  Replace the file with your own art (keep the same size), or just change
//  the path here to point at your own file. Sizes are noted on every line.
//
//  Beatmaps for Fan Club / Hole in One / Karate Man / Remix 9 / Blue Bird
//  were extracted automatically from the "perfect version" recordings you
//  provided - every tap is where the player hit in that recording. Times
//  are plain seconds in the JSON, so they're easy to hand-tune.
// =====================================================================

